SELECT region_id, sido_code, sido_name, gugun_code, gugun_name FROM regions
AND ( sido_name LIKE CONCAT('%', #{keyword}, '%') OR gugun_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY sido_name, gugun_name LIMIT #{limit} OFFSET #{offset}

SELECT region_id, sido_code, sido_name, gugun_code, gugun_name
FROM regions
WHERE region_id = #{regionId}
